  {
    "question": "How many distinct relations can be defined from a set A with 3 elements to a set B with 4 elements?",
    "options": {
      "A": "2^12 = 4096",
      "B": "2^10 = 1024",
      "C": "2^9 = 512",
      "D": "2^7 = 128"
    },
    "correct_answer": "A",
    "explanation": "A relation from A to B is any subset of the Cartesian product A×B. |A×B| = 3·4 = 12, so there are 2^12 possible subsets, i.e., 4096 relations.",
    "difficulty": "Medium"
  },
  {
    "question": "What is the power set of the set {x, y}?",
    "options": {
      "A": "{∅, {x}, {y}, {x, y}}",
      "B": "{∅, {x, y}}",
      "C": "{{x}, {y}}",
      "D": "{x, y, ∅}"
    },
    "correct_answer": "A",
    "explanation": "The power set contains every subset of the original set. For {x, y} the subsets are ∅, {x}, {y}, and {x, y}. Hence option A is correct.",
    "difficulty": "Medium"
  },
  {
    "question": "If f: X → Y and g: Y → Z are both injective (one‑to‑one), which statement about the composition g∘f is always true?",
    "options": {
      "A": "g∘f is injective",
      "B": "g∘f is surjective",
      "C": "g∘f is bijective",
      "D": "g∘f may fail to be a function"
    },
    "correct_answer": "A",
    "explanation": "When f and g are injective, distinct elements of X map to distinct elements of Y, and those distinct Y‑elements map to distinct Z‑elements. Hence g∘f never maps two different X‑elements to the same Z‑element, so it is injective.",
    "difficulty": "Medium"
  },
  {
    "question": "Define a relation R on a set S by aRb ⇔ |a − b| ≤ 2. Which property does R definitely satisfy?",
    "options": {
      "A": "Reflexive only",
      "B": "Symmetric only",
      "C": "Both Reflexive and Symmetric",
      "D": "Transitive only"
    },
    "correct_answer": "C",
    "explanation": "For any a, |a−a| = 0 ≤ 2, so R is reflexive. Since |a−b| = |b−a|, the condition is symmetric. Counter‑examples show R is not transitive, so only reflexive and symmetric are guaranteed.",
    "difficulty": "Medium"
  },
  {
    "question": "A function f: A → B possesses an inverse function f⁻¹: B → A. Which of the following must be true about f?",
    "options": {
      "A": "f is injective",
      "B": "f is surjective",
      "C": "f is bijective",
      "D": "f is neither injective nor surjective"
    },
    "correct_answer": "C",
    "explanation": "An inverse function exists only when every element of B is the image of exactly one element of A, i.e., f is both one‑to‑one (injective) and onto (surjective). Hence f must be bijective.",
    "difficulty": "Medium"
  }
]
